freeClass.source:
var PSFreeSpinObject = (function () {
                function PSFreeSpinObject() {
                    this.fsPlayed = false;
                    this.isRecovering = false;
                }
                Object.defineProperty(PSFreeSpinObject.prototype, "spinsLeft", {
                    get: function () {
                        var left = this.spinsTotal - this.currentSpin;
                        if (!isNaN(left) && left > -1) {
                            return left;
                        }
                        else if (this.spinsAwarded > 0) {
                            return this.spinsAwarded;
                        }
                        return 0;
                    },
                    enumerable: true,
                    configurable: true
                });
                Object.defineProperty(PSFreeSpinObject.prototype, "spinsLeftAtRecovery", {
                    get: function () {
                        var left = this.spinsLeft + 1;
                        if (left > this.spinsTotal) {
                            left = this.spinsTotal;
                        }
                        return left;
                    },
                    enumerable: true,
                    configurable: true
                });
                Object.defineProperty(PSFreeSpinObject.prototype, "requiresResume", {
                    get: function () {
                        return !this.fsPlayed && this.spinsLeft > 0;
                    },
                    enumerable: true,
                    configurable: true
                });
                Object.defineProperty(PSFreeSpinObject.prototype, "requiresFinalising", {
                    get: function () {
                        return !this.fsPlayed && this.currentSpin === this.spinsTotal;
                    },
                    enumerable: true,
                    configurable: true
                });
                Object.defineProperty(PSFreeSpinObject.prototype, "spinsLeftAfterNextSpin", {
                    get: function () {
                        var afterNext = this.spinsLeft - 1;
                        if (this.isRecovering) {
                            afterNext = this.spinsLeft;
                        }
                        return afterNext >= 0 ? afterNext : 0;
                    },
                    enumerable: true,
                    configurable: true
                });
                return PSFreeSpinObject;
            }());
            core.PSFreeSpinObject = PSFreeSpinObject;

