                        }
                        if (this._node.attributes.getNamedItem("currentSpin")) {
                            object.freeSpin.currentSpin = parseInt(this._node.attributes.getNamedItem("currentSpin").value);
                        }
                        if (this._node.attributes.getNamedItem("currentFSWins")) {
