featureParse.source:
function (input, object) {
                    _super.prototype.parse.call(this, input, object);
                    if (com.ps.reel.Reels.RESTORATION_LOGIC_RESPONSE) {
                        object.isRestorationResponse = true;
                        com.ps.reel.Reels.RESTORATION_LOGIC_RESPONSE = false;
                    }
                    for (var i = 0; i < this._resultNodes.length; i++) {
                        var childNode = this._resultNodes[i];
                        if (childNode.nodeName === "SubInfo") {
                            object.subInfo = new game.NemoSubInfoObject();
                            object.subInfo.descending = (childNode.attributes.getNamedItem("descending").value === "1");
                            object.subInfo.symbolValue = parseInt(childNode.attributes.getNamedItem("symbolValue").value);
                            object.subInfo.depthChange = parseInt(childNode.attributes.getNamedItem("depthChange").value);
                            object.subInfo.totalDepth = parseInt(childNode.attributes.getNamedItem("totalDepth").value);
                            object.subInfo.pressureChange = parseInt(childNode.attributes.getNamedItem("pressureChange").value);
                            object.subInfo.totalPressure = parseInt(childNode.attributes.getNamedItem("totalPressure").value);
                            object.subInfo.nextSpinReelLvl = parseInt(childNode.attributes.getNamedItem("nextSpinReelLvl").value);
                        }
                        else if (childNode.nodeName === "WildenedReels") {
                            object.wildenedReels = new game.NemoWildenedReelsObject();
                            var listSet = childNode.attributes.getNamedItem("changed").value.split("|");
                            object.wildenedReels.changed = [];
                            for (var x = 0; x < listSet.length; x++) {
                                object.wildenedReels.changed.push(parseInt(listSet[x]));
                            }
                        }
                        else if (childNode.nodeName === "PersistingWildsInfo") {
                            object.persistingWilds = new game.NemoPersistingWildsObject();
                            object.persistingWilds.positions = childNode.attributes.getNamedItem("positions").value.split("|");
                        }
                        else if (childNode.nodeName === "PressurizedWilds") {
                            object.pressurisedWilds = new game.NemoPressurizedWildsObject();
                            object.pressurisedWilds.expanded = childNode.attributes.getNamedItem("expanded").value.split("|");
                        }
                    }
                }

