playCommand.source:
function (logicResponse) {
                    var payload = [];
                    if (this._forceModel && this._forceModel.enabled && this._forceModel.forceData) {
                        payload.push(new core.PSForceEncoder(this._forceModel.forceData.positions, this._forceModel.forceData.index));
                        ps.utils.PSLog.log('- Force MakePlayRequestCmd::execute() - adding FORCE payload');
                    }
                    // Add HistoryReplay data if required
                    if (this._historyModel.getIsHistoryReplay()) {
                        var historyData = this._historyModel.getNextState(true);
                        if (historyData) {
                            ps.utils.PSLog.log("MakePlayRequestCmd::execute() - adding REPLAY payload");
                            payload.push(new core.PSReplayEncoder(historyData));
                        }
                        else {
                            ps.utils.PSLog.log("MakePlayRequestCmd::execute() - Do not send next LogicRequest, REPLAY is over.");
                            return;
                        }
                    }
                    var stakePerLine = this._stakeModel.getStakePerLine();
                    var totalStake = this._stakeModel.getTotalBet();
                    var lineCount = this._stakeModel.getLines();
                    var freeSpinsActive = (this._freeSpinsGameModel && this._freeSpinsGameModel.isInProgress());
                    payload.push(this._server.getStakeEncoder(stakePerLine, totalStake, lineCount, freeSpinsActive));
                    payload.push(this._server.getCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier));
                    this._server.addCustomPayloads(payload);
                    var data = new server.GLSRequest(payload);
                    //////////////////////////////
                    // Diagnostic purposes only
                    var initResponse = this._server.getInitResponse();
                    var recoveryRequest = initResponse.isRecovering;
                    if (!recoveryRequest) {
                        ps.utils.PSLog.log("MakePlayRequestCmd::execute() - normal logic request");
                        this.eventDispatcher.dispatchEvent(new core.GameEvent(core.GameEvent.SPIN_LOGIC_REQUEST_SENT));
                    }
                    else {
                        var initialRecoveryRequest = (logicResponse == undefined);
                        if (initialRecoveryRequest) {
                            ps.utils.PSLog.log("MakePlayRequestCmd::execute() - initial recovery logic request");
                        }
                        else {
                            ps.utils.PSLog.log("MakePlayRequestCmd::execute() - subsequent recovery logic request");
                            this.eventDispatcher.dispatchEvent(new core.GameEvent(core.GameEvent.SPIN_LOGIC_REQUEST_SENT));
                        }
                    }
                    this._server.makeLogicRequest(data);
                    //(<any>this._partnerAdapter).updateBet(0);
                    this._partnerAdapter.startedPlay();
                }

